}

/* 会话态主栏可能叠层较高，抬高侧栏保证「场景配置」等 nav 可点 */
.manus.manus--home-ai-session .manus-sidebar {
  z-index: 24;
}

.icon-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text);
  cursor: pointer;
}

.icon-btn:hover {
  border-color: var(--border);
  background: color-mix(in srgb, var(--bg) 70%, var(--code-bg));
}

.icon-btn svg {
  width: 18px;
  height: 18px;
}


.manus-center {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #fff;
  padding: 0 18px 64px;
  box-sizing: border-box;
}

/* 落地页主输入：整块 composer 卡片轻微外投影（含 textarea 区域） */
.manus-center .composer .composer-surface {
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.03),
    0 2px 8px -2px rgba(15, 23, 42, 0.04);
}

/* 输入区内侧极轻深度，与投影呼应 */
.manus-center .composer .composer-input {
  height: 160px;
  box-shadow: inset 0 1px 1px rgba(15, 23, 42, 0.02);
}

/* 首页发送后：同背景顶栏白底；消息区上移动画 + 底部 composer 下移收窄（与落地页同款 surface / 图标） */
.manus-home-session {
  flex: 1;
  height: 100%;
  max-height: 100%;
  min-height: 0;
  width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #ffffff;
  box-sizing: border-box;
}

.manus-home-session-head {
  flex-shrink: 0;
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  padding: 4px clamp(10px, 3vw, 16px);
  background: #ffffff;
  border-bottom: 1px solid #ececf0;
}

.manus-home-session-head__title {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.25;
  color: #0a0a0a;
  letter-spacing: 0.01em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 首页 Joyce 会话顶栏返回：仅本会话顶栏内略缩小高度，其它页同款类名不变 */
.manus-home-session-head .agents-joyce-main-chat-back {
  width: 38px;
  height: 38px;
  border: 0;
  background: transparent;
  border-radius: 8px;
}

.manus-home-session-head .agents-joyce-main-chat-back svg {
  width: 20px;
  height: 20px;
}

.manus-home-session-head .agents-joyce-main-chat-back:hover,
.manus-home-session-head .agents-joyce-main-chat-back:active {
  border-color: transparent;
  background: transparent;
}

.manus-home-session-body {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* 双列时：上区为草案/工作区 + 消息，底部 composer 通栏（宽度与落地页一致） */
.manus-home-session-split {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.manus-home-session-solo {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.manus-home-session-grid {
  flex: 1;
  min-height: 0;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  align-items: stretch;
  justify-content: stretch;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  transition: grid-template-columns 0.24s ease;
}

/* Plan：向左收拢整列草案侧栏，仅保留展开按钮条 */
.manus-home-session-grid--blueprint-collapsed {
  grid-template-columns: 48px minmax(0, 1fr);
}

.manus-home-session-grid--blueprint-collapsed .manus-home-session-side {
  min-width: 0;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint {
  flex: 1;
  min-height: 0;
  background: transparent;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-inner {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 8px 4px;
  overflow: hidden;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-inner-scroll {
  flex: 0 0 auto;
  min-height: 0;
  max-height: none;
  overflow: hidden !important;
  padding: 0;
}

/* 侧栏草案正文用了 display:flex，会盖掉 HTML [hidden] 的 display:none，折叠后须强制隐藏 */
.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-panel {
  display: none !important;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-header {
  position: relative;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0;
  margin: 0;
  padding: 10px 0;
  border-bottom: none;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-title {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-fold-btn {
  width: 40px;
  height: 38px;
}

.manus-home-session-grid--blueprint-collapsed .manus-plan-agent-blueprint-footer {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .manus-home-session-grid {
    transition: none;
  }
}

/* 草案/工作区 与 AI 对话区之间的可拖动分隔条 */
.manus-home-session-grid--session-split-resizing {
  transition: none !important;
}

.manus-home-session-grid-resizer {
  position: relative;
  z-index: 3;
  min-width: 0;
  width: auto;
  height: 100%;
  min-height: 40px;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  cursor: col-resize;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  box-sizing: border-box;
}

.manus-home-session-grid-resizer:focus {
  outline: none;
}

.manus-home-session-grid-resizer:focus-visible {
  outline: 2px solid var(--accent-border, #3b82f6);
  outline-offset: -1px;
}

.manus-home-session-grid-resizer::after {
  content: '';
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 50%;
  width: 3px;
  margin-left: -1.5px;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.14);
  pointer-events: none;
}

.manus-home-session-grid-resizer:hover::after,
.manus-home-session-grid--session-split-resizing .manus-home-session-grid-resizer::after {
  background: rgba(24, 144, 255, 0.55);
}

/* 分栏右侧：消息区 + 底部输入为同一列，随列宽与剩余高度一起变化 */
.manus-home-session-main-column {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  height: 100%;
  overflow: hidden;
  width: 100%;
  box-sizing: border-box;
}

.manus-home-session-main-column > .manus-home-session-chat {
  flex: 1;
  min-height: 0;
}

.manus-home-session-main-column > .manus-home-session-composer-band {
