  max-width: 100%;
  flex-shrink: 0;
}

.manus-home-session-side {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  height: 100%;
  overflow-x: hidden;
  overflow-y: visible;
  border-right: 1px solid #e8e8e8;
  background: #f0f0f2;
  box-sizing: border-box;
  padding: 0;
}

.manus-home-session-workspace {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  height: 100%;
  overflow: hidden;
  border-right: 1px solid #ececf0;
  background: #ffffff;
  box-sizing: border-box;
}

.manus-home-session-workspace > .manus-build-workspace {
  flex: 1;
  min-height: 0;
}

/* Build 分栏：工作区与分割条相邻，去掉重复竖线 */
.manus-home-session-grid--build-split .manus-home-session-workspace {
  border-right: none;
}

.manus-home-session-chat {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.manus-home-session-solo .manus-home-session-chat {
  flex: 1;
}

.manus-home-session-messages-wrap {
  flex: 1;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  padding: 12px clamp(12px, 4vw, 24px) 8px;
  box-sizing: border-box;
  animation: manus-home-session-messages-rise 0.48s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.manus-home-session-messages {
  flex: 1;
  min-height: 0;
  width: 100%;
  max-width: min(760px, 100%);
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
  /* 始终隐藏滚动条，仍可滚轮 / 触控板 / 键盘滚动 */
  scrollbar-width: none;
  -ms-overflow-style: none;
