.manus-home-session-messages-inner--wf-steps .manus-wf-pipeline-card__step-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  min-width: 32px;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border-radius: 8px;
  background: #2563eb;
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0;
  box-shadow: 0 1px 3px rgba(37, 99, 235, 0.35);
