/* ── composer mode tab bar（composer-surface 上方，紧贴无间距） ── */
.composer-mode-tabs {
  display: inline-flex;
  flex-direction: row;
  align-items: flex-end;
  gap: 0;
  padding: 0;
  margin-bottom: 0;
  width: max-content;
  max-width: 100%;
  background: #f4f4f4;
  border-radius: 16px 20px 0 0;
  position: relative;
  z-index: 1;
}

.composer-mode-tab {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: 16px 20px 0 0;
  background: #f4f4f5;
  color: #999999;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  position: relative;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
  white-space: nowrap;
  box-sizing: border-box;
}

.composer-mode-tab.is-active {
  background: #ffffff;
  color: #18181b;
  border-color: #e6e6e6;
  border-bottom: 1px solid #ffffff;
  /* 用负 margin 盖住 surface 的顶部边框，让 tab 与 surface 无缝衔接 */
  margin-bottom: -2px;
  z-index: 2;
}

.composer-mode-tab > span {
  position: relative;
  z-index: 2;
}

.composer-mode-tab.is-active::before,
.composer-mode-tab.is-active::after {
  content: '';
  position: absolute;
  bottom: 0;
  width: 18px;
  height: 18px;
  pointer-events: none;
  z-index: -1;
}

.composer-mode-tab.is-active::before {
  left: -18px;
  border-bottom-right-radius: 18px;
  box-shadow: 9px 9px 0 8px #ffffff;
}

.composer-mode-tab.is-active:first-child::before {
  display: none;
}

.composer-mode-tab.is-active::after {
  right: -18px;
  border-bottom-left-radius: 18px;
  box-shadow: -9px 9px 0 8px #ffffff;
}

.composer-mode-tab:not(.is-active):hover {
  color: #555555;
  background: #eeeeef;
  border-color: #ebebeb;
}

.composer-mode-tab-ic {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: currentColor;
}

.composer-mode-tab-ic svg {
  display: block;
}

