  background: #ffffff;
  padding: 10px 12px;
  box-sizing: border-box;
}

.agents-back-panel .agents-back-btn {
  width: auto;
  max-width: none;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  box-sizing: border-box;
}

/* 返回条内标题：与返回键同一行，整体左对齐 */
.agents-back-panel--with-title {
