  flex-direction: row;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  padding-top: 10px;
  padding-bottom: 10px;
}

.agents-back-panel--with-title .agents-back-btn {
  flex-shrink: 0;
}

.agents-back-panel-title {
  flex: 1;
  min-width: 0;
  margin: 0;
  max-width: 100%;
  font-size: 16px;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--text-heading);
  line-height: 1.3;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scenario-workspace-title-editor {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1;
}

.scenario-workspace-title-editor .agents-back-panel-title {
  flex: 0 1 auto;
}

.scenario-workspace-title-editor__trigger {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: #71717a;
  cursor: pointer;
  opacity: 0;
  flex-shrink: 0;
  transition:
    opacity 0.15s ease,
    background 0.15s ease,
    color 0.15s ease;
}

.scenario-workspace-title-editor:hover .scenario-workspace-title-editor__trigger,
.scenario-workspace-title-editor:focus-within .scenario-workspace-title-editor__trigger {
  opacity: 1;
}

.scenario-workspace-title-editor--locked .scenario-workspace-title-editor__trigger {
  opacity: 0.45;
}

.scenario-workspace-title-editor__trigger:hover {
  background: #f4f4f5;
  color: #18181b;
}

.scenario-workspace-title-editor__trigger.is-disabled,
.scenario-workspace-title-editor__trigger:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.scenario-workspace-title-editor:hover .scenario-workspace-title-editor__trigger.is-disabled,
.scenario-workspace-title-editor:hover .scenario-workspace-title-editor__trigger:disabled {
  opacity: 0.45;
}

.scenario-workspace-title-editor--editing {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
}

.scenario-workspace-title-editor__input {
  flex: 1;
  min-width: 0;
  height: 32px;
  padding: 0 10px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  background: #fff;
  color: var(--text-heading);
  font: inherit;
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.02em;
  box-sizing: border-box;
}

.scenario-workspace-title-editor__input:focus {
  outline: 2px solid rgba(37, 99, 235, 0.18);
  outline-offset: 1px;
  border-color: #93c5fd;
}

.scenario-workspace-title-editor__actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.scenario-workspace-title-editor__cancel,
.scenario-workspace-title-editor__save {
  height: 32px;
  padding: 0 10px;
  border-radius: 8px;
  font: inherit;
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
}

.scenario-workspace-title-editor__cancel {
  border: 1px solid #e4e4e7;
  background: #fff;
  color: #52525b;
}

.scenario-workspace-title-editor__cancel:hover {
  background: #fafafa;
}

.scenario-workspace-title-editor__save {
  border: 1px solid #18181b;
  background: #18181b;
  color: #fff;
}

.scenario-workspace-title-editor__save:hover:not(:disabled) {
  background: #27272a;
}

.scenario-workspace-title-editor__save:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* 场景工作区：左侧返回+标题，中间 Editor / Runs 分段控件 */
.agents-back-panel--with-title.agents-back-panel--with-workspace-segment {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: 12px;
  border-bottom: 1px solid rgba(24, 24, 27, 0.06);
}

.agents-back-panel-lead {
  grid-column: 1;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  min-width: 0;
  justify-self: start;
}

.agents-back-panel--with-workspace-segment .agents-workspace-segment {
  grid-column: 2;
  justify-self: center;
}

.agents-back-panel-trail {
  grid-column: 3;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  justify-self: end;
}

.scenario-workspace-more-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.scenario-workspace-more-btn {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #fff;
  color: #52525b;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.scenario-workspace-more-btn:hover,
.scenario-workspace-more-wrap:focus-within .scenario-workspace-more-btn {
  background: #fafafa;
  border-color: #d4d4d8;
  color: #18181b;
}

.scenario-workspace-more-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 40;
  width: max-content;
  min-width: 128px;
  padding: 5px;
  border: 1px solid #e4e7ef;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.12);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.12s ease, visibility 0.12s ease;
}

.scenario-workspace-more-menu::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  height: 10px;
}

.scenario-workspace-more-wrap:hover .scenario-workspace-more-menu,
.scenario-workspace-more-wrap:focus-within .scenario-workspace-more-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.scenario-workspace-more-menu-item {
  display: block;
  width: 100%;
  padding: 7px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: #18181b;
  font: inherit;
  font-size: 13px;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
}

.scenario-workspace-more-menu-item:hover {
  background: #f4f4f5;
}

.scenario-workspace-more-menu-item--danger {
  color: #dc2626;
}

.scenario-workspace-more-menu-item--danger:hover {
  background: #fef2f2;
}

.scenario-workspace-more-menu-item:disabled,
.scenario-workspace-more-menu-item.is-disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.scenario-workspace-more-menu-item.is-disabled:hover,
.scenario-workspace-more-menu-item:disabled:hover {
  background: transparent;
}

.scenario-workspace-more-menu-item--danger.is-disabled:hover,
.scenario-workspace-more-menu-item--danger:disabled:hover {
  background: transparent;
}

.agents-workspace-segment {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  padding: 3px;
  border-radius: 999px;
  background: #f4f4f5;
  border: 1px solid #e4e4e7;
  box-sizing: border-box;
  gap: 2px;
}

/* 场景工作区顶栏：Build / Runs 胶囊分段（浅灰轨道 + 选中项白底浮起） */
.agents-workspace-segment--build-runs {
  padding: 4px;
  gap: 0;
  min-width: 168px;
  background: #eceef2;
  border-color: #e2e8f0;
}

.agents-workspace-segment__btn {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid transparent;
  border-radius: 16px;
  font: inherit;
  font-size: 14px;
  font-weight: 550;
  line-height: 1.2;
  cursor: pointer;
  background: transparent;
  color: #71717a;
  box-sizing: border-box;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    box-shadow 0.15s ease,
    border-color 0.15s ease;
}

.agents-workspace-segment--build-runs .agents-workspace-segment__btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 7px 12px;
  gap: 7px;
  font-weight: 500;
  color: #64748b;
}

.agents-workspace-segment--build-runs .agents-workspace-segment__btn:hover[aria-selected='false'] {
  color: #475569;
}

.agents-workspace-segment__btn[aria-selected='true'] {
  background: #ffffff;
  color: #18181b;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.1);
}

.agents-workspace-segment--build-runs .agents-workspace-segment__btn[aria-selected='true'] {
  font-weight: 650;
  color: #0f172a;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.06),
