  border-color: rgba(226, 232, 240, 0.98);
}

.agents-workspace-segment__btn:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.agents-workspace-segment__btn.is-disabled,
.agents-workspace-segment__btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.agents-workspace-segment__icon {
  display: block;
  flex-shrink: 0;
}

.agents-workspace-segment__icon svg {
