  border: 1px solid #e4e4e7;
  background: #f4f4f5;
  font-size: 14px;
  font-weight: 650;
  color: #18181b;
}

.agents-back-panel--with-title.agents-back-panel--with-workspace-run {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid rgba(24, 24, 27, 0.06);
}

.scenario-workflow-run-topbar-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
