  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.scenario-workflow-run-workers-grid.scenario-workflow-run-workers-grid--linear {
  grid-template-columns: 1fr;
  gap: 10px;
}

.scenario-workflow-run-worker-card {
  border: 1px solid rgba(226, 232, 240, 0.94);
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
  overflow: hidden;
}

.scenario-workflow-run-worker-card.is-done {
  border-color: rgba(226, 232, 240, 0.94);
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

.scenario-workflow-run-worker-head {
  width: 100%;
  padding: 16px 16px 14px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  border: none;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.scenario-workflow-run-worker-head-side {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.scenario-workflow-run-worker-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.scenario-workflow-run-worker-kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

.scenario-workflow-run-worker-copy strong {
  font-size: 15px;
  font-weight: 740;
  line-height: 1.3;
  color: #0f172a;
}

.scenario-workflow-run-worker-copy > span:last-child {
  font-size: 12px;
  line-height: 1.6;
  color: #64748b;
}

.scenario-workflow-run-worker-status {
  width: fit-content;
  max-width: 100%;
  min-height: 30px;
  padding: 0 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  background: #f4f4f5;
  color: #64748b;
}

.scenario-workflow-run-worker-status.is-running {
  background: #f3f0ff;
  color: #6d28d9;
}

.scenario-workflow-run-worker-status.is-done {
  background: #ecfdf3;
  color: #15803d;
}

.scenario-workflow-run-worker-status-ic {
  width: 12px;
  height: 12px;
  border: 2px solid rgba(99, 102, 241, 0.16);
  border-top-color: #6366f1;
  border-radius: 50%;
  animation: scenario-workflow-run-spin 0.9s linear infinite;
}

.scenario-workflow-run-worker-status-ic.is-idle {
  border-color: #d4d4d8;
  animation: none;
}

.scenario-workflow-run-worker-status-ic.is-done {
  border: none;
  width: 14px;
  height: 14px;
  animation: none;
  position: relative;
}

.scenario-workflow-run-worker-status-ic.is-done::before {
  content: '✓';
  display: block;
  line-height: 14px;
}

.scenario-workflow-run-worker-body {
  padding: 14px 16px 16px;
}

.scenario-workflow-run-worker-brief {
  padding: 12px 13px;
  border: 1px solid #ebeef5;
  border-radius: 14px;
  background: rgba(248, 250, 252, 0.9);
}

.scenario-workflow-run-worker-brief-row {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px solid rgba(226, 232, 240, 0.8);
}

.scenario-workflow-run-worker-brief-row:last-child {
  padding-bottom: 0;
  border-bottom: none;
}

.scenario-workflow-run-worker-brief-row:first-child {
  padding-top: 0;
}

.scenario-workflow-run-worker-brief-row span {
  font-size: 12px;
  color: #94a3b8;
}

.scenario-workflow-run-worker-brief-row strong {
  font-size: 12px;
  line-height: 1.65;
  color: #334155;
}

.scenario-workflow-run-worker-steps {
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.scenario-workflow-run-worker-step {
  padding: 10px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 12px;
  background: #f8fafc;
  color: #6b7280;
  font-size: 14px;
}

.scenario-workflow-run-worker-step.is-active {
  background: #f5f3ff;
  color: #5b21b6;
}

.scenario-workflow-run-worker-step.is-done {
  background: #f8fafc;
  color: #0f172a;
}

.scenario-workflow-run-worker-step-ic {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  border-radius: 50%;
  border: 2px solid #d1d5db;
}

.scenario-workflow-run-worker-step-ic.is-active {
  border-color: rgba(99, 102, 241, 0.16);
  border-top-color: #6366f1;
  animation: scenario-workflow-run-spin 0.9s linear infinite;
}

.scenario-workflow-run-worker-step-ic.is-done {
  border: none;
  background: #22c55e;
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  animation: none;
}

.scenario-workflow-run-results-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.scenario-workflow-run-results-header strong {
  font-size: 16px;
  color: #111827;
}

.scenario-workflow-run-results {
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.scenario-workflow-run-result-card {
  padding: 18px;
  border: 1px solid rgba(226, 232, 240, 0.94);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.04);
}

.scenario-workflow-run-result-card--summary {
  border-color: #ddd6fe;
  background: linear-gradient(180deg, #ffffff 0%, #faf5ff 100%);
}

.scenario-workflow-run-result-title {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 12px;
}

.scenario-workflow-run-result-title strong {
  font-size: 15px;
  color: #111827;
}

.scenario-workflow-run-result-title span {
  font-size: 14px;
  color: #64748b;
}

.scenario-workflow-run-report-shell {
  padding: 18px;
}

.scenario-workflow-run-report-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.scenario-workflow-run-report-head-copy strong {
  display: block;
  margin-top: 4px;
  font-size: 18px;
  font-weight: 780;
  color: #0f172a;
}

.scenario-workflow-run-report-kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #4f46e5;
}

.scenario-workflow-run-report-head-copy p {
  margin: 8px 0 0;
  max-width: 760px;
  font-size: 14px;
  line-height: 1.72;
  color: #64748b;
}

.scenario-workflow-run-report-status {
  min-height: 32px;
  padding: 0 12px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #ecfdf3;
  color: #15803d;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.scenario-workflow-run-report-section,
.scenario-workflow-run-report-summary {
  padding: 16px;
  border: 1px solid #e8ecf4;
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
}

.scenario-workflow-run-report-section-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
}

.scenario-workflow-run-report-section-head > span {
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #eef2ff;
  color: #4f46e5;
  font-size: 12px;
  font-weight: 800;
}

.scenario-workflow-run-report-section-head strong,
.scenario-workflow-run-report-summary-head strong {
  display: block;
  font-size: 15px;
  font-weight: 760;
  color: #0f172a;
}

.scenario-workflow-run-report-section-head p,
.scenario-workflow-run-report-summary-head span {
  margin: 4px 0 0;
  font-size: 14px;
  color: #64748b;
}

.scenario-workflow-run-report-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.scenario-workflow-run-code-shell {
  margin-top: 14px;
  border: 1px solid rgba(30, 41, 59, 0.08);
  border-radius: 16px;
  background: #0f172a;
  overflow: hidden;
}

.scenario-workflow-run-code-toolbar {
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(15, 23, 42, 0.92);
}

.scenario-workflow-run-code-toolbar-left,
.scenario-workflow-run-code-toolbar-right {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.scenario-workflow-run-code-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #475569;
}

.scenario-workflow-run-code-dot:first-child {
  background: #f87171;
}

.scenario-workflow-run-code-dot:nth-child(2) {
  background: #fbbf24;
}

.scenario-workflow-run-code-dot:nth-child(3) {
  background: #4ade80;
}

.scenario-workflow-run-code-toolbar-right span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #94a3b8;
}

.scenario-workflow-run-code-block {
  margin: 0;
  padding: 14px 16px;
  overflow: auto;
  background: #0f172a;
  color: #e5e7eb;
  font-size: 12px;
  line-height: 1.7;
}

.scenario-workflow-run-report-summary-head {
  margin-bottom: 12px;
}

.scenario-workflow-run-report-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.scenario-workspace-runs {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
  box-sizing: border-box;
  background: #f6f6f6;
}

.scenario-workspace-runs-placeholder {
  margin: 0;
  max-width: 420px;
  text-align: center;
  font-size: 14px;
  line-height: 1.55;
  color: #71717a;
}

.scenario-workspace-runs-shell {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  position: relative;
}

.scenario-workspace-runs-sidebar {
  width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid #e4e4e7;
  background: #f9f9fb;
  box-sizing: border-box;
}

.scenario-workspace-runs-sidebar-toolbar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 12px 12px 10px;
  flex-shrink: 0;
}

.scenario-workspace-runs-icon-btn {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: #52525b;
  cursor: pointer;
}

.scenario-workspace-runs-icon-btn:hover {
  background: #f4f4f5;
}

.scenario-workspace-runs-new-task {
  margin-left: auto;
  height: 34px;
  padding: 0 14px;
  border: none;
  border-radius: 8px;
  background: #18181b;
  color: #ffffff;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.scenario-workspace-runs-new-task:hover {
  background: #050625;
}

/* 分段 Tab：与顶栏 .agents-workspace-segment / __btn 视觉一致 */
.scenario-workspace-runs-tabs {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 2px;
  margin: 0 12px 10px;
  padding: 3px;
  flex-shrink: 0;
  border-radius: 999px;
  background: #f4f4f5;
  border: 1px solid #e4e4e7;
  box-sizing: border-box;
}

.scenario-workspace-runs-tab {
  flex: 1;
  min-height: 0;
  margin: 0;
  padding: 6px 14px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: #71717a;
  font: inherit;
  font-size: 14px;
  font-weight: 550;
  line-height: 1.2;
  cursor: pointer;
  box-sizing: border-box;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    box-shadow 0.15s ease;
}

.scenario-workspace-runs-tab:hover:not(.is-active) {
  color: #3f3f46;
}

.scenario-workspace-runs-tab.is-active {
  background: #ffffff;
  color: #18181b;
  font-weight: 550;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.1);
}

.scenario-workspace-runs-tab:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.scenario-workspace-runs-list {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 4px 10px 16px;
  box-sizing: border-box;
}

.scenario-workspace-runs-section-label {
  padding: 18px 4px 8px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #18181b;
}

.scenario-workspace-runs-section-label:first-child {
  padding-top: 6px;
}

.scenario-workspace-runs-item {
  display: block;
  width: 100%;
  margin: 0 0 4px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  text-align: left;
  cursor: pointer;
  font: inherit;
  box-sizing: border-box;
}

.scenario-workspace-runs-item:hover:not(.is-active) {
  background: #f4f4f5;
}

.scenario-workspace-runs-item.is-active {
  background: #ebe9fe;
  border-color: #e4e4f0;
}

.scenario-workspace-runs-item.is-active .scenario-workspace-runs-pill {
  background: rgba(255, 255, 255, 0.82);
}

.scenario-workspace-runs-item.is-active .scenario-workspace-runs-pill--text {
  background: rgba(255, 255, 255, 0.92);
}

.scenario-workspace-runs-item-row {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.scenario-workspace-runs-item-title {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  font-weight: 600;
  color: #18181b;
  line-height: 1.35;
}

.scenario-workspace-runs-item-meta {
  flex-shrink: 0;
  margin: 0;
  font-size: 14px;
  font-weight: 400;
  color: #a1a1aa;
  line-height: 1.35;
}

.scenario-workspace-runs-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.scenario-workspace-runs-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 3px 8px 3px 6px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.35;
  background: #f4f4f5;
  color: #52525b;
  box-sizing: border-box;
}

.scenario-workspace-runs-pill--text {
  padding-left: 8px;
  background: #fafafa;
  border: 1px solid #e4e4e7;
}

.scenario-workspace-runs-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.scenario-workspace-runs-pill--purple .scenario-workspace-runs-pill-dot {
  background: #3b82f6;
}

.scenario-workspace-runs-pill--green .scenario-workspace-runs-pill-dot {
  background: #22c55e;
}

.scenario-workspace-runs-pill--amber .scenario-workspace-runs-pill-dot {
  background: var(--warning-500);
}

.scenario-workspace-runs-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: #f6f6f6;
}

.scenario-workspace-runs-main-head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid #e4e4e7;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.05);
  background: #ffffff;
}

.scenario-workspace-runs-main-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: #18181b;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scenario-workspace-runs-main-head-actions {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.scenario-workspace-runs-main-report {
  flex-shrink: 0;
  height: 38px;
  padding: 0 14px;
  border-radius: 8px;
  border: 1px solid #e4e4e7;
  background: #ffffff;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: #3f3f46;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workspace-runs-main-report:hover {
  border-color: #93c5fd;
  background: #eff6ff;
  color: #18181b;
}

.scenario-workspace-runs-main-report:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workspace-runs-main-restart {
  flex-shrink: 0;
  height: 38px;
  padding: 0 14px;
  border-radius: 8px;
  border: 1px solid #e4e4e7;
  background: #ffffff;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: #18181b;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workspace-runs-main-restart:hover {
  border-color: #93c5fd;
  background: #eff6ff;
}

.scenario-workspace-runs-main-restart:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

/* Runs 面板 · Report：入职流程自动化执行报告弹窗 */
.scenario-workspace-runs-exec-modal-root {
  position: fixed;
  inset: 0;
  z-index: 10060;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  box-sizing: border-box;
}

.scenario-workspace-runs-exec-modal-backdrop {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 0;
  border: none;
  background: rgba(15, 23, 42, 0.48);
  cursor: pointer;
}

.scenario-workspace-runs-exec-modal-panel {
  position: relative;
  z-index: 1;
  width: min(800px, 100%);
  max-height: min(90vh, 840px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid #e4e4e7;
  background: #ffffff;
  box-shadow: 0 24px 48px rgba(15, 23, 42, 0.18);
  box-sizing: border-box;
}

.scenario-workspace-runs-exec-modal-head {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px 12px;
  border-bottom: 1px solid #f4f4f5;
  flex-shrink: 0;
}

.scenario-workspace-runs-exec-modal-title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.35;
  color: #1e3a8a;
  letter-spacing: -0.02em;
}

.scenario-workspace-runs-exec-modal-close {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  margin: -4px -6px 0 0;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: #71717a;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.scenario-workspace-runs-exec-modal-close:hover {
  background: #f4f4f5;
  color: #18181b;
}

.scenario-workspace-runs-exec-modal-close:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workspace-runs-exec-modal-body {
  padding: 16px 18px 20px;
  overflow: auto;
  flex: 1;
  min-height: 0;
}

.scenario-workspace-runs-exec-hero {
  padding: 14px 16px 16px;
  margin-bottom: 18px;
  border-radius: 12px;
  background: #f4f4f5;
  border: 1px solid #e4e4e7;
}

.scenario-workspace-runs-exec-hero-time {
  margin: 0 0 14px;
  font-size: 14px;
  color: #71717a;
}

.scenario-workspace-runs-exec-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.scenario-workspace-runs-exec-metric {
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid #e4e4e7;
