  text-transform: none;
  color: #334155;
}

.runs-agent-exec-extract-caption {
  margin: 10px 0 8px;
  font-size: 12px;
  line-height: 1.5;
  color: #52525b;
}

.runs-agent-exec-extract-caption strong {
  font-weight: 650;
  color: #3f3f46;
}

.runs-agent-exec-tasks {
  margin-top: 0;
}

ul.runs-agent-exec-steps {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: flex;
  flex-direction: column;
