.runs-agent-exec-step--ok .runs-agent-exec-step-ic {
  color: #16a34a;
}

.runs-agent-exec-step--warn .runs-agent-exec-step-ic {
  color: var(--warning-800);
}

.runs-agent-exec-step--pending .runs-agent-exec-step-ic {
