}

.runs-agent-exec-step-label {
  color: #18181b;
  font-weight: 500;
}

.runs-agent-exec-step-detail {
  font-size: 12px;
  color: #71717a;
}

.runs-agent-exec-outputs {
  margin: 0 0 12px;
  border-radius: 10px;
  border: 1px solid #e4e4e7;
  overflow: hidden;
  background: #ffffff;
}

.runs-agent-exec-output-row {
