}

.runs-agent-exec-json-cap--button {
  width: 100%;
  margin: 0;
  border: 0;
  cursor: pointer;
  font: inherit;
  color: inherit;
  text-align: left;
  box-sizing: border-box;
  -webkit-appearance: none;
  appearance: none;
  transition: background-color 0.15s ease;
}

.runs-agent-exec-json-cap--button:hover {
  background: #1e293b;
}

.runs-agent-exec-json-cap--button:focus-visible {
