  background: #ffffff;
  font-size: 10px;
  font-weight: 700;
  color: #52525b;
  line-height: 1;
}

.runs-agent-post-exec-review-text {
  flex: 1;
  min-width: 0;
}

.scenario-workspace-runs-run-hint--interaction {
  margin-top: 0;
}

