  background: transparent;
  color: var(--text-heading);
  cursor: pointer;
  font: inherit;
  font-size: 14px;
}

.agents-back-btn:hover {
  background: transparent;
}

/* 工作区：中间主栏整块（含顶栏 + 下方编排区），非独立卡片 */
.scenario-workspace {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  width: 100%;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: #f6f6f6;
  box-sizing: border-box;
}

.scenario-workspace > .agents-header.agents-header--with-back {
  flex-shrink: 0;
  width: 100%;
  margin-left: 0;
  margin-right: 0;
  max-width: none;
  background: #ffffff;
}

/* Build 视图：左侧无遮罩配置抽屉 + 右侧画布（无全屏遮罩层） */
.scenario-workspace-build {
  flex: 1;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  position: relative;
  background: #f6f6f6;
  /* 各侧栏抽屉统一宽度（条件分支 / 收集 / 手动配置等） */
  --scenario-workspace-drawer-width: min(368px, 35vw);
  --scenario-workspace-drawer-min-width: 276px;
}

.scenario-workspace-build-main {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* 条件分支节点专用：左侧无遮罩抽屉（仅 branch 节点打开） */
.scenario-branch-drawer {
  width: var(--scenario-workspace-drawer-width);
  min-width: var(--scenario-workspace-drawer-min-width);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-right: 1px solid #e4e4e7;
  box-sizing: border-box;
  z-index: 4;
  min-height: 0;
  box-shadow: 6px 0 28px rgba(15, 23, 42, 0.06);
}

/* @ 资源弹窗打开时抬高侧栏，避免与右侧画布叠层冲突 */
.scenario-branch-drawer:has(.scenario-collect-drawer-mentionbar-at-trigger[aria-expanded='true']) {
  z-index: 30;
}

.scenario-branch-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 16px 12px;
  flex-shrink: 0;
  border-bottom: 1px solid #f4f4f5;
}

.scenario-branch-drawer-title {
  margin: 0;
  font-size: 16px;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--text-heading);
}

.scenario-branch-drawer-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  scrollbar-width: thin;
  scrollbar-color: #c4c4cc #f0f0f2;
}

.scenario-branch-drawer-body::-webkit-scrollbar {
  width: 4px;
}

.scenario-branch-drawer-body::-webkit-scrollbar-track {
  background: #f0f0f2;
  border-radius: 4px;
}

.scenario-branch-drawer-body::-webkit-scrollbar-thumb {
  background: #c4c4cc;
  border-radius: 4px;
}

.scenario-branch-drawer-body::-webkit-scrollbar-thumb:hover {
  background: #a1a1aa;
}

/* Trigger 节点：左侧「更改触发器」无遮罩抽屉（壳层与 .scenario-collect-drawer 对齐） */
.scenario-trigger-drawer {
  z-index: 4;
