  top: 0;
  z-index: 0;
  /* auto：子级命中区可接收悬停/点击；可见 path 使用 --visible 关闭命中，避免挡画布平移 */
  pointer-events: auto;
  display: block;
  overflow: visible;
  box-sizing: border-box;
}

.scenario-workflow-edge-group {
  pointer-events: auto;
}

.scenario-workflow-edge-path--visible {
  pointer-events: none;
}

.scenario-workflow-edge-hit {
  fill: none;
  stroke: rgba(0, 0, 0, 0);
  stroke-width: 14;
  pointer-events: stroke;
  cursor: default;
}

.scenario-workflow-edge-hover-add-fo {
  overflow: visible;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease;
}

.scenario-workflow-edge-group:hover .scenario-workflow-edge-hover-add-fo {
  opacity: 1;
  pointer-events: auto;
}

.scenario-workflow-edge-hover-add-btn {
