  cursor: pointer;
}

.scenario-workflow-card-workspace-row--branch-canvas {
  align-items: stretch;
}

.scenario-workflow-card-workspace-main--branch-canvas {
  flex-direction: column;
  align-items: stretch;
  gap: 0;
}

.scenario-workflow-branch-canvas {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 200px;
  min-height: 200px;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-tabs {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: flex-end;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
  width: 100%;
  min-width: 0;
