.scenario-workflow-branch-canvas-tabs-inner {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: flex-end;
  gap: 6px;
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
}

.scenario-workflow-branch-canvas-tab {
  margin: 0;
  padding: 8px 14px 10px;
  border: 1px solid #e4e4e7;
  border-bottom: none;
  border-radius: 10px 10px 0 0;
  background: #f4f4f5;
  color: #71717a;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.2;
  cursor: pointer;
  box-sizing: border-box;
  font-family: inherit;
  position: relative;
  z-index: 0;
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.scenario-workflow-branch-canvas-tab-overflow {
  margin: 0;
  padding: 8px 10px 10px;
  border: 1px solid #e4e4e7;
  border-bottom: none;
  border-radius: 10px 10px 0 0;
  background: #f4f4f5;
  color: #71717a;
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  cursor: pointer;
  box-sizing: border-box;
  font-family: inherit;
  position: relative;
  z-index: 0;
  flex-shrink: 0;
  min-width: 44px;
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
}

.scenario-workflow-branch-canvas-tab-overflow:hover {
  background: #ececf0;
  color: #52525b;
}

.scenario-workflow-branch-canvas-tab-overflow--active {
  z-index: 2;
  background: #f5f7ff;
  color: #2563eb;
  border-color: #c7d2fe;
  border-bottom-color: #f5f7ff;
  margin-bottom: -1px;
  padding-bottom: 11px;
  box-shadow: 0 1px 0 0 #f5f7ff;
}

.scenario-workflow-branch-canvas-tab-overflow-inner {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 2px;
}

.scenario-workflow-branch-canvas-tab-overflow-label {
  display: inline-block;
}

.scenario-workflow-branch-canvas-tab-overflow-chevron {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
  color: inherit;
  opacity: 0.72;
  transition: transform 0.15s ease;
}

.scenario-workflow-branch-canvas-tab-overflow-chevron--open {
  transform: rotate(180deg);
}

.scenario-workflow-branch-overflow-menu {
  padding: 6px 0;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow:
    0 4px 6px -1px rgba(15, 23, 42, 0.08),
    0 14px 28px -6px rgba(15, 23, 42, 0.14);
  box-sizing: border-box;
}

.scenario-workflow-branch-overflow-menu-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  width: 100%;
  margin: 0;
  padding: 9px 14px;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  color: #3f3f46;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workflow-branch-overflow-menu-item:hover {
  background: #f4f4f5;
}

.scenario-workflow-branch-overflow-menu-item--current {
  background: #eef2ff;
  color: #2563eb;
}

.scenario-workflow-branch-overflow-menu-mark {
  font-weight: 600;
}

.scenario-workflow-branch-overflow-menu-sep {
  margin: 0 2px;
  opacity: 0.65;
}

.scenario-workflow-branch-overflow-menu-suffix {
  font-weight: 500;
}

.scenario-workflow-branch-canvas-tab--active {
  z-index: 2;
  /* 与下方 rulebar 同为浅蓝底 #f5f7ff */
  background: #f5f7ff;
  color: #2563eb;
  border-color: #c7d2fe;
  border-bottom-color: #f5f7ff;
  margin-bottom: -1px;
  padding-bottom: 11px;
  box-shadow: 0 1px 0 0 #f5f7ff;
}

.scenario-workflow-branch-canvas-tab-mark {
  font-weight: 600;
}

.scenario-workflow-branch-canvas-tab-sep {
  margin: 0 4px;
  opacity: 0.7;
}

.scenario-workflow-branch-canvas-tab-suffix {
  font-weight: 500;
}

.scenario-workflow-branch-canvas-tab-add {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  margin: 0 0 1px 2px;
  padding: 0;
  border: 1px solid #e4e4e7;
  border-radius: 8px;
  background: #fafafa;
  flex-shrink: 0;
  color: #71717a;
  cursor: pointer;
  box-sizing: border-box;
  font-family: inherit;
}

.scenario-workflow-branch-canvas-tab-add:hover:not(:disabled) {
  background: #f4f4f5;
  color: #52525b;
}

.scenario-workflow-branch-canvas-tab-add:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.scenario-workflow-branch-canvas-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  margin-top: -1px;
  border: 1px solid #c7d2fe;
  border-radius: 0 10px 10px 10px;
  background: #ffffff;
  overflow: hidden;
  z-index: 1;
}

.scenario-workflow-branch-canvas-rulebar-wrap {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  width: 100%;
  background: #f5f7ff;
  border-bottom: 1px solid #e0e7ff;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-rulebar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  flex: 1 1 0;
  min-width: 0;
  margin: 0;
  padding: 10px 10px 10px 14px;
  background: transparent;
  border: none;
  font-size: 14px;
  font-family: inherit;
  color: #3f3f46;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-rulebar:hover {
  background: rgba(238, 242, 255, 0.85);
}

.scenario-workflow-branch-canvas-rulebar-more-btn {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin: 0;
  padding: 0 12px 0 6px;
  border: none;
  background: transparent;
  color: #a1a1aa;
  cursor: pointer;
  box-sizing: border-box;
  font-family: inherit;
}

.scenario-workflow-branch-canvas-rulebar-more-btn:hover {
  color: #71717a;
  background: rgba(238, 242, 255, 0.85);
}

.scenario-workflow-branch-canvas-rulebar-more-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 0;
}

.scenario-workflow-branch-canvas-rulebar-wrap:hover .scenario-workflow-branch-canvas-rulebar-more-btn {
  color: #71717a;
}

.scenario-workflow-branch-canvas-rulebar:focus-visible,
.scenario-workflow-branch-canvas-rulebar-more-btn:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
  z-index: 1;
}

.scenario-workflow-branch-canvas-rule-idx {
  font-weight: 600;
  color: #a1a1aa;
  min-width: 1em;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.scenario-workflow-branch-canvas-rule-label {
  flex: 1 1 0;
  min-width: 0;
  font-weight: 500;
  color: #52525b;
  text-align: left;
}

.scenario-workflow-branch-rulebar-menu {
  padding: 6px 0;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow:
    0 4px 6px -1px rgba(15, 23, 42, 0.08),
    0 14px 28px -6px rgba(15, 23, 42, 0.14);
  box-sizing: border-box;
}

.scenario-workflow-branch-rulebar-menu-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  width: 100%;
  margin: 0;
  padding: 8px 12px;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 14px;
  color: #18181b;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workflow-branch-rulebar-menu-item:hover:not(:disabled) {
  background: #f4f4f5;
}

.scenario-workflow-branch-rulebar-menu-item:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.scenario-workflow-branch-rulebar-menu-item--sub {
  justify-content: flex-start;
}

.scenario-workflow-branch-rulebar-menu-item--danger {
  color: #dc2626;
}

.scenario-workflow-branch-rulebar-menu-item--danger .scenario-workflow-branch-rulebar-menu-ic {
  color: #dc2626;
}

.scenario-workflow-branch-rulebar-menu-item--danger:hover:not(:disabled) {
  background: #fef2f2;
}

.scenario-workflow-branch-rulebar-menu-ic {
  display: flex;
  flex-shrink: 0;
  width: 18px;
  align-items: center;
  justify-content: center;
  color: #52525b;
}

.scenario-workflow-branch-rulebar-menu-text {
  flex: 1 1 0;
  min-width: 0;
}

.scenario-workflow-branch-rulebar-menu-chevron {
  display: flex;
  flex-shrink: 0;
  margin-left: auto;
  color: #a1a1aa;
}

.scenario-workflow-branch-rulebar-menu-divider {
  height: 1px;
  margin: 6px 10px;
  background: #e5e7eb;
}

.scenario-workflow-branch-rulebar-menu-item-wrap {
  position: relative;
}

.scenario-workflow-branch-rulebar-submenu {
  position: absolute;
  left: calc(100% - 4px);
  top: 0;
  z-index: 2;
  min-width: 128px;
  max-height: 240px;
  overflow-y: auto;
  padding: 6px 0;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow:
    0 4px 6px -1px rgba(15, 23, 42, 0.08),
    0 12px 20px -6px rgba(15, 23, 42, 0.12);
  box-sizing: border-box;
}

.scenario-workflow-branch-rulebar-submenu-item {
  display: block;
  width: 100%;
  margin: 0;
  padding: 8px 12px;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 14px;
  color: #3f3f46;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workflow-branch-rulebar-submenu-item:hover:not(:disabled) {
  background: #f4f4f5;
}

.scenario-workflow-branch-rulebar-submenu-item:disabled {
  opacity: 0.45;
  cursor: default;
}

.scenario-workflow-branch-canvas-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
  padding: 12px 14px 14px;
  background: #ffffff;
}

.scenario-workflow-branch-canvas-body--with-steps > .scenario-workflow-branch-canvas-email-steps {
  flex: 1 1 auto;
  min-height: 0;
  flex-shrink: 1;
  overflow-y: auto;
  padding-bottom: 10px;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-body-foot {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  margin-top: auto;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-body--with-steps .scenario-workflow-branch-canvas-body-foot {
  align-items: center;
}

.scenario-workflow-branch-canvas-body:not(.scenario-workflow-branch-canvas-body--with-steps)
  .scenario-workflow-branch-canvas-body-foot {
  flex: 1 1 auto;
  min-height: 0;
}

.scenario-workflow-branch-canvas-body:not(.scenario-workflow-branch-canvas-body--with-steps)
  .scenario-workflow-branch-canvas-add-step {
  flex: 1;
  min-height: 88px;
}

.scenario-workflow-branch-canvas-email-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-shrink: 0;
  width: 100%;
}

/* 条件分支画布：示例步骤条（路径 A 且规则为「信息完整」时标题为信息整理Agent，否则信息补充Agent） */
.scenario-workflow-branch-canvas-showcase-step-wrap {
  width: 100%;
  flex-shrink: 0;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-body--with-steps > .scenario-workflow-branch-canvas-showcase-step-wrap {
  flex: 1 1 auto;
  min-height: 0;
  padding-bottom: 10px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.scenario-workflow-branch-canvas-body--with-steps
  > .scenario-workflow-branch-canvas-showcase-step-wrap
  > .scenario-workflow-branch-canvas-email-steps {
  flex: 1 1 auto;
  min-height: 0;
  flex-shrink: 1;
  overflow-y: auto;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-showcase-step {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  width: 100%;
  margin: 0;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #ffffff;
  box-sizing: border-box;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
  overflow: hidden;
}

.scenario-workflow-branch-canvas-showcase-step--clickable {
  cursor: pointer;
}

.scenario-workflow-branch-canvas-showcase-step--clickable:hover {
  border-color: #d4d4d8;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.07);
}

.scenario-workflow-branch-canvas-showcase-step--clickable:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workflow-branch-canvas-showcase-step-accent {
  flex-shrink: 0;
  width: 3px;
  background: #3b82f6;
}

.scenario-workflow-branch-canvas-showcase-step-inner {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1 1 auto;
  padding: 11px 14px 11px 12px;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-showcase-step-idx {
  flex-shrink: 0;
  min-width: 1.25ch;
  font-size: 14px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: #a1a1aa;
  line-height: 1.2;
}

.scenario-workflow-branch-canvas-showcase-step-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  background: #ffffff;
  border: 1px solid #e4e4e7;
  color: #7c3aed;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05);
}

.scenario-workflow-branch-canvas-showcase-step-icon svg {
  display: block;
}

.scenario-workflow-branch-canvas-showcase-step-main {
  flex: 1 1 auto;
  min-width: 0;
}

.scenario-workflow-branch-canvas-showcase-step-title {
  font-size: 14px;
  font-weight: 400;
  color: #050625;
  letter-spacing: -0.01em;
  line-height: 1.35;
}

.scenario-workflow-branch-canvas-email-step {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 8px 10px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #f8fafc;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-email-step--editable {
  cursor: pointer;
}

.scenario-workflow-branch-canvas-email-step--editable:hover {
  background: #f1f5f9;
  border-color: #d4d4d8;
}

.scenario-workflow-branch-canvas-email-step--editable:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workflow-branch-canvas-email-step-badge {
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #f87171, #dc2626);
}

.scenario-workflow-branch-canvas-email-step-badge svg {
  width: 16px;
  height: 16px;
}

.scenario-workflow-branch-canvas-email-step-badge--gmail-outlined {
  background: #ffffff;
  border: 1px solid #e4e4e7;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
}

.scenario-workflow-branch-canvas-email-step-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.scenario-workflow-branch-canvas-email-step-title {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-heading);
  line-height: 1.35;
}

.scenario-workflow-branch-canvas-email-step-actions {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease;
}

.scenario-workflow-branch-canvas-email-step:hover .scenario-workflow-branch-canvas-email-step-actions,
.scenario-workflow-branch-canvas-email-step-actions:focus-within {
  opacity: 1;
  pointer-events: auto;
}

.scenario-workflow-branch-canvas-email-step-edit,
.scenario-workflow-branch-canvas-email-step-delete {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  color: #71717a;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.1);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.scenario-workflow-branch-canvas-email-step-edit:hover {
  background: #eff6ff;
  color: #2563eb;
}

.scenario-workflow-branch-canvas-email-step-edit:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workflow-branch-canvas-email-step-delete:hover {
  background: #fef2f2;
  color: #dc2626;
}

.scenario-workflow-branch-canvas-email-step-delete:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.scenario-workflow-branch-canvas-add-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 88px;
  margin: 0;
  padding: 16px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #fafafa;
  color: #2563eb;
  font-size: 14px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-workflow-branch-canvas-add-step:hover {
  background: #f4f4f5;
  border-color: #c7d2fe;
}

.scenario-workflow-branch-canvas-add-step-ic {
  display: block;
  flex-shrink: 0;
}

/* 已成功添加步骤后：底部紧凑「添加步骤」 */
.scenario-workflow-branch-canvas-add-step-inline {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  padding: 4px 16px;
  border: 1px solid #e4e4e7;
  border-radius: 999px;
  background: #ffffff;
  color: #71717a;
  font-family: inherit;
  line-height: 1.2;
  cursor: pointer;
  box-sizing: border-box;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  transition:
    background 0.12s ease,
    border-color 0.12s ease,
    box-shadow 0.12s ease;
}

.scenario-workflow-branch-canvas-add-step-inline:hover {
  background: #fafafa;
  border-color: #d4d4d8;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.08);
}

.scenario-workflow-branch-canvas-add-step-inline-ic {
  display: flex;
  flex-shrink: 0;
  color: #a1a1aa;
}

.scenario-workflow-branch-canvas-add-step-inline-label {
  color: #71717a;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.scenario-workflow-card-icon-wrap {
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: 7px;
  background: #f4f4f5;
  border: 1px solid #e4e4e7;
  display: grid;
  place-items: center;
  box-sizing: border-box;
}

.scenario-workflow-card-icon-wrap--collect {
  color: #2563eb;
}

/* 「+ New」— 智能体：容器与 Trigger 菜单项一致（底/边来自 .scenario-workflow-card-icon-wrap） */
