  font-size: 14px;
  color: var(--text-heading);
}

.managerial-agent-preview-body {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 320px;
}

.managerial-agent-preview-thread {
  flex: 1;
  min-height: 220px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.managerial-agent-preview-turn {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}

.managerial-agent-preview-turn.is-user {
  align-items: flex-end;
}

.managerial-agent-preview-sender {
  font-size: 12px;
  font-weight: 600;
  color: #667085;
}

.managerial-agent-preview-bubble {
  max-width: min(100%, 340px);
  padding: 12px 14px;
  border-radius: 14px 14px 14px 6px;
  background: #f7f8fb;
  color: #111827;
  line-height: 1.55;
  box-shadow: inset 0 0 0 1px #edf0f5;
}

.managerial-agent-preview-bubble.is-user {
  border-radius: 14px 14px 6px 14px;
  background: #111827;
  color: #ffffff;
  box-shadow: none;
}

.managerial-agent-preview-files {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.managerial-agent-preview-file-chip {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  color: inherit;
  font-size: 12px;
  font-weight: 500;
}

.single-agent-preview-placeholder {
  color: #8f93a6;
}

.single-agent-preview-input-row {
  padding: 14px 16px 16px;
  border-top: 1px solid #edf0f5;
  display: flex;
}

.managerial-agent-preview-input-row {
  align-items: stretch;
}

.managerial-agent-preview-composer {
  flex: 1;
  min-width: 0;
  position: relative;
  min-height: 96px;
  padding: 10px 12px 12px;
  border: 1px solid #dfe3eb;
  border-radius: 12px;
  background: #ffffff;
}

.managerial-agent-preview-attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 8px 2px;
}

.managerial-agent-preview-attachment-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 0 10px;
  border: 1px solid #e4e7ec;
  border-radius: 999px;
  background: #f8fafc;
  color: #344054;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
}

.managerial-agent-preview-attach-btn {
  position: absolute;
  left: 12px;
  bottom: 12px;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #667085;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.managerial-agent-preview-attach-btn svg {
  width: 18px;
  height: 18px;
}

.managerial-agent-preview-actions {
  position: absolute;
  right: 12px;
  bottom: 10px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.managerial-agent-preview-input {
  min-height: 72px;
  height: auto;
  padding: 2px 92px 28px 40px;
  border: 0;
  background: transparent;
  box-shadow: none;
  resize: none;
  line-height: 1.5;
  overflow: auto;
}

.single-agent-preview-send {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 10px;
  background: #9b9b9b;
  color: #ffffff;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition:
    background 120ms ease,
    transform 120ms ease,
    opacity 120ms ease;
}

.managerial-agent-preview-voice {
  width: 33px;
  height: 33px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #667085;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.managerial-agent-preview-voice svg {
  width: 27px;
  height: 27px;
}

.managerial-agent-preview-voice.is-listening {
  color: #4d6bff;
}

.single-agent-preview-send svg {
  width: 18px;
  height: 18px;
}

.single-agent-preview-send:hover:not(:disabled) {
  background: #7f7f7f;
  transform: translateY(-1px);
}

.single-agent-preview-send:disabled {
  background: #c7c7c7;
  cursor: not-allowed;
  opacity: 0.92;
}

.managerial-agent-preview-composer:hover {
  background: #ffffff;
}

.managerial-agent-preview-composer:focus-within {
  border-color: #cfd6e4;
  box-shadow: 0 0 0 3px rgba(77, 107, 255, 0.08);
}

.managerial-agent-preview-input:hover,
.managerial-agent-preview-input:focus {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  outline: none;
}

.managerial-agent-preview-input::placeholder {
  color: #667085;
}

.single-agent-modal-layer {
  position: fixed;
  inset: 0;
  z-index: 12000;
}

.single-agent-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(17, 24, 39, 0.28);
  backdrop-filter: blur(3px);
}

.single-agent-modal {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(560px, calc(100vw - 32px));
  transform: translate(-50%, -50%);
  padding: 22px 22px 24px;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.18);
}

.single-agent-modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: #71717a;
  font-size: 22px;
  line-height: 1;
  font-weight: 400;
  cursor: pointer;
  box-sizing: border-box;
}

.single-agent-modal-close:hover:not(:disabled) {
  background: #f4f4f5;
  color: #18181b;
}

.single-agent-modal-close:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.single-agent-modal-close:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

.single-agent-modal-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-heading);
}

.single-agent-modal-subtitle {
  margin-top: 10px;
  font-size: 15px;
  line-height: 1.5;
  color: #5f667f;
}

.single-agent-template-list {
  margin-top: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.single-agent-template-chip {
  padding: 8px 10px;
  border: 1px solid #dbe1f0;
  border-radius: 999px;
  background: #ffffff;
  color: var(--text-heading);
  font-size: 12px;
  font-weight: 400;
  cursor: pointer;
}

.single-agent-template-chip.is-active,
.single-agent-template-chip:hover {
  border-color: rgba(77, 107, 255, 0.44);
  background: rgba(77, 107, 255, 0.06);
  color: #3554eb;
}

.single-agent-modal-textarea {
  margin-top: 20px;
  min-height: 0;
  height: calc(1.5em * 3 + 24px);
  max-height: calc(1.5em * 3 + 24px);
  overflow-y: auto;
  resize: none;
}

.single-agent-modal-textarea--detail {
  height: min(320px, 48vh);
  max-height: min(320px, 48vh);
}

.single-agent-modal-preview {
  margin: 16px 0 0;
  max-height: 220px;
  overflow: auto;
  padding: 14px;
  border: 1px solid #e6eaf5;
  border-radius: 14px;
  background: #fafbff;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
  line-height: 1.55;
  color: #2f3552;
}

.single-agent-modal-actions {
  margin-top: 18px;
  display: flex;
  width: 100%;
  gap: 10px;
}

.single-agent-modal-actions > button {
  flex: 1 1 0;
  min-width: 0;
}

.single-agent-modal-cancel {
  height: 44px;
  padding: 0 18px;
  border: 1px solid #e4e4e7;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  color: #171826;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
}

.single-agent-modal-cancel:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.single-agent-modal-submit {
  height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #050625;
  color: #ffffff;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
}

.single-agent-modal-submit.is-loading {
  opacity: 0.92;
}

.single-agent-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #ffffff;
  border-radius: 999px;
  animation: single-agent-spin 0.8s linear infinite;
}

@keyframes single-agent-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 820px) {
  .agents-toolbar {
    flex-direction: column;
    align-items: stretch;
  }
  .agents-toolbar-right {
    align-items: stretch;
  }
}

@media (max-width: 1180px) {
  .single-agent-topbar {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .single-agent-topbar-right {
    justify-content: flex-start;
  }

  .single-agent-layout {
    grid-template-columns: 1fr;
  }

  .managerial-agent-page .single-agent-layout.managerial-agent-layout--advanced-open {
    --managerial-columns-height: calc(100vh - 112px);
    grid-template-columns: minmax(420px, 1.02fr) minmax(360px, 0.9fr) minmax(300px, 0.7fr);
    min-width: 1120px;
    overflow: visible;
  }

  .managerial-agent-page .single-agent-topbar {
    grid-template-columns: minmax(640px, 1fr) auto;
    min-width: 1120px;
    align-items: center;
  }

  .managerial-agent-page .single-agent-topbar-right {
    justify-content: flex-start;
  }

  .managerial-agent-grid {
    grid-template-columns: 1fr;
  }

  .manager-agent-row {
    grid-template-columns: 40px minmax(0, 1fr) 40px 40px;
  }

  .manager-agent-select-wrap,
  .manager-agent-usage-input {
    grid-column: span 3;
  }

  .manager-agent-action-row {
    grid-template-columns: 1fr;
  }

  .single-agent-preview-card {
    min-height: 420px;
  }

  .managerial-agent-page .single-agent-layout:not(.managerial-agent-layout--advanced-open) > .single-agent-right {
    position: static;
    height: auto;
    min-height: 0;
    max-height: none;
  }

  .managerial-agent-page
    .single-agent-layout:not(.managerial-agent-layout--advanced-open)
    > .single-agent-right
    > .managerial-agent-preview-card {
    height: auto;
    max-height: none;
    min-height: 420px;
  }
}

@media (max-width: 720px) {
  .single-agent-shell {
    padding: 14px;
  }

  .single-agent-topbar-left,
  .single-agent-topbar-right {
    flex-wrap: wrap;
  }

  .single-agent-card {
    padding: 14px;
  }

  .single-agent-modal {
    width: min(100vw - 20px, 560px);
    padding: 18px;
  }

  .single-agent-modal-title {
    font-size: 22px;
  }
}

.onboarding-workflow-page {
  min-height: 100vh;
  background: linear-gradient(180deg, #ffffff 0%, #fbfcfe 100%);
}

.onboarding-workflow-shell {
  padding: 0;
}

.onboarding-workflow-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
}

.onboarding-workflow-header-main {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
}

.onboarding-workflow-back {
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  color: #ffffff;
  background: linear-gradient(135deg, #6f63ff 0%, #8a57ff 100%);
