  gap: 12px;
}

.workflow-panel-eyebrow,
.workflow-canvas-title,
.workflow-joyce-title,
.workflow-joyce-composer-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #777a92;
}

.workflow-panel-title {
  margin-top: 6px;
  font-size: 18px;
  font-weight: 650;
  color: #17171f;
}

.workflow-canvas-title,
.workflow-joyce-title {
  font-size: 16px;
  text-transform: none;
  letter-spacing: 0;
  color: #181926;
}

.workflow-canvas-subtitle,
.workflow-joyce-subtitle,
.workflow-panel-helper {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.55;
  color: #80839a;
}

.workflow-panel-color-chip {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.8);
