@media (max-width: 1360px) {
  .onboarding-workflow-body.is-joyce-collapsed {
    grid-template-columns: 300px minmax(0, 1fr);
  }
}

@media (max-width: 1360px) {
  .onboarding-workflow-body {
    grid-template-columns: 300px minmax(0, 1fr);
  }

  .workflow-joyce-shell {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1040px) {
  .onboarding-workflow-header {
    flex-direction: column;
    align-items: stretch;
  }

  .onboarding-workflow-actions {
    flex-wrap: wrap;
  }

  .onboarding-workflow-body {
    grid-template-columns: 1fr;
  }

  .workflow-canvas-surface {
    height: 560px;
  }
}

@media (max-width: 720px) {
  .onboarding-workflow-shell {
    padding: 14px;
  }

  .onboarding-workflow-tabs {
    width: 100%;
    overflow-x: auto;
  }

  .workflow-config-shell,
  .workflow-joyce-shell,
  .workflow-canvas-shell {
    padding: 14px;
  }

  .workflow-canvas-surface {
    height: 480px;
  }
}

/* Onboarding workflow layout refinement */
.onboarding-workflow-page {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-height: 100vh;
  background:
    radial-gradient(circle at top, rgba(122, 98, 255, 0.08), transparent 22%),
    linear-gradient(180deg, #f7f4ee 0%, #f7f4ee 100%);
}

.onboarding-workflow-shell {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 100vh;
  padding: 0;
}

.onboarding-workflow-stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  height: 100vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
