}

.onboarding-workflow-topbar-left,
.onboarding-workflow-topbar-right {
  min-width: 0;
  display: flex;
  align-items: center;
}

.onboarding-workflow-topbar-left {
  gap: 10px;
}

.onboarding-workflow-topbar-center {
  justify-self: center;
}

.onboarding-workflow-topbar-right {
  margin-left: auto;
}

.onboarding-workflow-content {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #ffffff 0%, #fcfcfd 100%);
}

.onboarding-workflow-placeholder {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
}

.onboarding-workflow-placeholder-text {
  font-size: 14px;
  font-weight: 500;
  color: #9aa1ad;
}

.onboarding-workflow-meta {
  min-width: 0;
}

.onboarding-workflow-title {
  font-size: 15px;
  font-weight: 600;
  color: #17191f;
}

.onboarding-workflow-subtitle {
  margin-top: 2px;
  font-size: 11px;
  color: #8f94a3;
}

.onboarding-workflow-back {
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid #e7eaf0;
  border-radius: 10px;
  background: #ffffff;
  color: #4b5563;
