  border: 1px solid #e7ecf3;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.05);
}

.onboarding-workflow-run-modal-column--preview {
  overflow: hidden;
}

.onboarding-workflow-run-modal-section-head {
  padding: 18px 18px 14px;
  border-bottom: 1px solid #f0f2f6;
}

.onboarding-workflow-run-modal-section-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
  color: #111827;
}

.onboarding-workflow-run-modal-section-head p {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: #667085;
}

.onboarding-workflow-run-modal-fields {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 18px;
}

.onboarding-workflow-run-modal-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.onboarding-workflow-run-modal-field span {
  font-size: 13px;
  font-weight: 600;
  color: #344054;
}

.onboarding-workflow-run-modal-input {
  width: 100%;
  height: 44px;
  padding: 0 14px;
  border: 1px solid #d8dee8;
  border-radius: 12px;
  background: #ffffff;
