}

.onboarding-workflow-run-modal-input--date {
  padding-right: 46px;
  cursor: pointer;
}

.onboarding-workflow-run-modal-input--date::-webkit-calendar-picker-indicator {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.onboarding-workflow-run-modal-date-trigger {
  position: absolute;
  top: 50%;
  right: 12px;
  transform: translateY(-50%);
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #667085;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.18s ease, color 0.18s ease;
}

.onboarding-workflow-run-modal-date-trigger:hover {
  background: #f5f7fb;
  color: #5b5bd6;
}

.onboarding-workflow-run-modal-input:focus {
  outline: none;
  border-color: #5b5bd6;
  box-shadow: 0 0 0 3px rgba(91, 91, 214, 0.12);
}

.onboarding-workflow-run-modal-preview-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  overflow: auto;
}

.onboarding-workflow-run-modal-preview-card {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 12px;
  align-items: flex-start;
  padding: 14px;
  border: 1px solid #e7ecf3;
  border-radius: 14px;
  background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
}

.onboarding-workflow-run-modal-preview-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: #2f6bff;
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
}

.onboarding-workflow-run-modal-preview-main {
  min-width: 0;
}

.onboarding-workflow-run-modal-preview-main h4 {
  margin: 0 0 10px;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  color: #111827;
}

.onboarding-workflow-run-modal-preview-description {
  margin: 0;
  font-size: 14px;
  line-height: 1.7;
  color: #344054;
}

.onboarding-workflow-run-modal-preview-token {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin: 0 2px;
  padding: 0 8px;
  border-radius: 8px;
  background: #2f6bff;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.5;
  vertical-align: baseline;
}

.onboarding-workflow-run-modal-expected {
  margin-top: 14px;
  padding: 12px 14px;
  border: 1px solid #e8edf5;
  border-radius: 12px;
  background: #fafbff;
}

.onboarding-workflow-run-modal-expected-label {
  display: inline-flex;
  margin-bottom: 6px;
  font-size: 12px;
  font-weight: 700;
  color: #475467;
}

.onboarding-workflow-run-modal-expected p {
  margin: 0;
  font-size: 13px;
  line-height: 1.7;
  color: #475467;
}

.onboarding-workflow-run-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 24px 20px;
  border-top: 1px solid #eef0f4;
  background: #ffffff;
}

.workflow-canvas-column {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  padding: 0;
  transition: padding 180ms ease;
}

.onboarding-workflow-stage.is-panel-open .workflow-canvas-column {
  padding-left: var(--scenario-workspace-drawer-width);
}

.workflow-canvas-shell,
.workflow-canvas-surface {
  height: 100%;
}

.workflow-canvas-shell {
  display: flex;
  flex: 1 1 auto;
  width: 100%;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  padding: 0;
}

.workflow-canvas-shell.is-agent-template-drop-over {
  position: relative;
}

.workflow-canvas-surface {
  position: relative;
  flex: 1 1 auto;
  width: 100%;
  margin-top: 0;
  min-height: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background:
    radial-gradient(circle, rgba(17, 24, 39, 0.055) 1px, transparent 1.2px),
    linear-gradient(180deg, #ffffff 0%, #fbfcfd 100%);
  background-size:
    18px 18px,
    auto;
  background-position:
    top left,
    center;
}

.workflow-canvas-drop-hint {
  position: absolute;
  left: 50%;
  top: 18px;
  transform: translateX(-50%);
  z-index: 5;
  min-height: 34px;
  padding: 0 16px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(103, 95, 255, 0.96);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 14px 26px rgba(103, 95, 255, 0.22);
  pointer-events: none;
  opacity: 0;
  transition: opacity 160ms ease, transform 160ms ease;
}

.workflow-canvas-drop-hint.is-active {
  opacity: 1;
}

.onboarding-reactflow .react-flow__pane {
  background: transparent;
}

.onboarding-reactflow .react-flow__controls {
  left: 8px;
  bottom: 10px;
}

.onboarding-reactflow .react-flow__controls,
.onboarding-reactflow .react-flow__minimap {
  border: 1px solid #e7eaf0;
  border-radius: 18px;
  box-shadow: 0 10px 24px rgba(17, 24, 39, 0.05);
}

.onboarding-reactflow .react-flow__minimap {
  background: rgba(255, 255, 255, 0.96);
}

.workflow-agent-node {
  position: relative;
  width: 300px;
  padding: 14px;
  border: 1px solid #eceff4;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow:
    0 4px 12px rgba(17, 24, 39, 0.03),
    0 1px 0 rgba(255, 255, 255, 0.9);
  backdrop-filter: none;
}

.workflow-agent-node.is-tool-dragging {
  border-style: dashed;
  border-width: 2px;
  border-color: #76a7ff;
  background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
  box-shadow:
    0 6px 16px rgba(70, 120, 255, 0.06),
    inset 0 0 0 1px rgba(118, 167, 255, 0.08);
}

.workflow-agent-node.is-tool-drop-over {
  border-color: #5f95ff;
  background: linear-gradient(180deg, #ffffff 0%, #f2f7ff 100%);
  box-shadow:
    0 8px 18px rgba(70, 120, 255, 0.08),
    inset 0 0 0 1px rgba(95, 149, 255, 0.12);
}

.workflow-agent-node.is-selected {
  border-color: color-mix(in srgb, var(--workflow-node-accent) 20%, #e5e7eb);
  box-shadow:
    0 6px 16px rgba(17, 24, 39, 0.05),
    0 0 0 3px color-mix(in srgb, var(--workflow-node-accent) 8%, #ffffff);
}

.workflow-agent-node.is-runtime-busy {
  border-color: rgba(121, 163, 255, 0.78);
  box-shadow:
    0 10px 24px rgba(73, 121, 255, 0.08),
    0 0 0 2px rgba(73, 121, 255, 0.08);
}

.workflow-agent-node.is-runtime-running {
  border-color: rgba(91, 91, 214, 0.76);
  box-shadow:
    0 12px 26px rgba(91, 91, 214, 0.14),
    0 0 0 3px rgba(91, 91, 214, 0.08);
}

.workflow-agent-node.is-runtime-completed {
  border-color: rgba(64, 185, 80, 0.66);
  box-shadow:
    0 10px 24px rgba(52, 199, 89, 0.1),
    0 0 0 2px rgba(52, 199, 89, 0.08);
}

.workflow-agent-node.is-tool-dragging.is-selected,
.workflow-agent-node.is-tool-drop-over.is-selected {
  box-shadow:
    0 8px 18px rgba(70, 120, 255, 0.08),
    0 0 0 3px rgba(118, 167, 255, 0.14);
}

.workflow-agent-runtime-badge {
  position: absolute;
  top: -12px;
  right: 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.12);
  z-index: 2;
}

.workflow-agent-runtime-badge--busy {
  background: #e8f1ff;
  color: #3a68d8;
}

.workflow-agent-runtime-badge--running {
  background: #ece9ff;
  color: #5b46d6;
}

.workflow-agent-runtime-badge--completed {
  background: #e9f9ee;
  color: #1f9d46;
}

.workflow-agent-runtime-badge-icon {
  position: relative;
  flex-shrink: 0;
  width: 12px;
  height: 12px;
}

.workflow-agent-runtime-badge-icon.is-spinning {
  border: 1.8px solid currentColor;
  border-right-color: transparent;
  border-radius: 999px;
  animation: workflow-agent-runtime-spin 0.9s linear infinite;
}

.workflow-agent-runtime-badge-icon.is-busy::before,
.workflow-agent-runtime-badge-icon.is-busy::after {
  content: '';
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 999px;
  background: currentColor;
}

.workflow-agent-runtime-badge-icon.is-busy::before {
  top: 0;
  width: 8px;
  height: 4px;
}

.workflow-agent-runtime-badge-icon.is-busy::after {
  bottom: 0;
  width: 6px;
  height: 6px;
}

.workflow-agent-runtime-badge-icon.is-check::before {
  content: '';
  position: absolute;
  left: 3px;
  top: 1px;
  width: 4px;
  height: 7px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
}

@keyframes workflow-agent-runtime-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.workflow-agent-drop-pill {
  position: absolute;
  left: 50%;
  top: -12px;
  transform: translateX(-50%);
  height: 22px;
  padding: 0 10px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #5d8ff3;
  color: #ffffff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.01em;
  box-shadow: 0 8px 18px rgba(93, 143, 243, 0.26);
  pointer-events: none;
}

/* 与 .scenario-workflow-card .scenario-workflow-card-icon-wrap--workspace-agent 一致 */
.workflow-agent-node-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid #e4e4e7;
  box-sizing: border-box;
  display: grid;
  place-items: center;
  color: #7c3aed;
