  border: 1px solid #e4e4e7;
  border-radius: 8px;
  background: #ffffff;
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  cursor: pointer;
  box-shadow: none;
}

.experience-record-create-btn:hover {
  border-color: #c7d2fe;
  background: #eef2ff;
  color: #312e81;
}

.experience-record-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  padding: 18px 18px 16px;
  border: 1px solid #e4e4e7;
  border-radius: 18px;
  background: #ffffff;
}

.experience-record-row-main,
.experience-record-row-side {
  min-width: 0;
}

.experience-record-row-side {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 8px;
  min-width: 108px;
}

.experience-record-delete-btn {
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid #fecaca;
  border-radius: 10px;
  background: #ffffff;
  color: #dc2626;
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
}

.experience-record-delete-btn:hover {
  background: #fef2f2;
  border-color: #fca5a5;
}

.experience-record-row-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.experience-record-row-person,
.experience-record-row-stage {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.experience-record-row-person strong {
  font-size: 15px;
  font-weight: 650;
  color: #111827;
}

.experience-record-row-person span {
  font-size: 12px;
  color: #8a94a6;
}

.experience-record-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  background: #f5f3ff;
  color: #6d4cff;
  font-size: 11px;
  font-weight: 700;
}

.experience-record-chip.is-muted {
  background: #f4f4f5;
  color: #71717a;
}

.experience-record-row-preview {
  margin-top: 10px;
  font-size: 14px;
  line-height: 1.65;
  color: #4b5563;
}

.experience-record-row-meta {
  margin-top: 14px;
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr) auto;
  align-items: center;
  gap: 14px;
}

.experience-record-progress {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  color: #6b7280;
}

.experience-record-progress strong {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
}

.experience-record-progress-bar {
  height: 8px;
  border-radius: 999px;
  background: #f4f4f5;
  overflow: hidden;
}

.experience-record-progress-bar span {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, #8b5cf6 0%, #6f63ff 100%);
}

.experience-record-summary {
  font-size: 12px;
  color: #6b7280;
  white-space: nowrap;
}

.experience-record-detail-scroll {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.experience-record-detail-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.experience-record-detail-metric,
.experience-record-detail-summary-card,
.experience-record-node-card,
.experience-record-pending-item {
  border: 1px solid #e4e4e7;
  border-radius: 18px;
  background: #ffffff;
}

.experience-record-detail-metric {
  padding: 16px;
}

.experience-record-detail-metric span {
  display: block;
  font-size: 12px;
  color: #8a94a6;
}

.experience-record-detail-metric strong {
  display: block;
  margin-top: 8px;
  font-size: 16px;
  font-weight: 700;
  color: #111827;
}

.experience-record-detail-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.experience-record-detail-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.experience-record-detail-section-head h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #111827;
}

.experience-record-detail-section-head span {
  font-size: 12px;
  color: #8a94a6;
}

.experience-record-detail-summary-card {
  padding: 18px;
}

.experience-record-detail-summary-card p {
  margin: 0;
  font-size: 14px;
  line-height: 1.7;
  color: #4b5563;
}

.experience-record-detail-chip-row {
  margin-top: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.experience-record-detail-chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 12px;
  border-radius: 999px;
  background: #f4f4f5;
  color: #52525b;
  font-size: 12px;
  font-weight: 600;
}

.experience-record-node-list,
.experience-record-pending-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.experience-record-node-card {
  padding: 16px 16px 14px;
}

.experience-record-node-card.is-completed {
  background: #fafafa;
}

.experience-record-node-card.is-active {
  background: #f5f3ff;
  border-color: #ddd6fe;
}

.experience-record-node-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.experience-record-node-title {
  font-size: 15px;
  font-weight: 650;
  color: #111827;
}

.experience-record-node-agent {
  margin-top: 4px;
  font-size: 12px;
  color: #8a94a6;
}

.experience-record-node-body {
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.experience-record-node-row {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 12px;
}

.experience-record-node-row span {
  font-size: 12px;
  font-weight: 600;
  color: #6b7280;
}

.experience-record-node-row p {
  margin: 0;
  font-size: 14px;
  line-height: 1.65;
  color: #4b5563;
}

.experience-record-pending-item {
  padding: 14px 16px;
  font-size: 14px;
  line-height: 1.6;
  color: #4b5563;
}

.experience-record-pending-item.is-complete {
  background: #fafafa;
  color: #52525b;
}

@media (max-width: 960px) {
  .experience-record-detail-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .experience-record-row,
  .experience-record-row-meta {
    grid-template-columns: 1fr;
  }

  .experience-record-row-side {
    justify-content: flex-start;
  }
}

@media (max-width: 720px) {
  .experience-records-overlay {
    padding: 16px;
  }

  .experience-records-modal,
  .experience-records-modal--detail {
    width: min(100%, calc(100vw - 32px));
    max-height: calc(100vh - 32px);
    max-height: calc(100dvh - 32px);
  }

  .experience-records-modal-head,
  .experience-records-list,
  .experience-record-detail-scroll {
    padding-left: 16px;
    padding-right: 16px;
  }

  .experience-records-modal-head {
    flex-direction: column;
  }

  .experience-records-modal-head-actions {
    width: 100%;
    justify-content: space-between;
  }

  .experience-record-detail-summary {
    grid-template-columns: 1fr;
  }

  .experience-record-node-row {
    grid-template-columns: 1fr;
    gap: 6px;
  }
}

.experience-shell {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: var(--experience-sidebar-width) minmax(0, 1fr);
  gap: clamp(14px, 1.6vw, 22px);
  width: min(100%, 1680px);
  height: 100%;
  min-height: 0;
  margin: 0 auto;
  align-items: stretch;
}

.experience-records-stage {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  width: min(100%, 1680px);
  min-height: 0;
  margin: 0 auto;
}

.experience-sidebar {
  display: grid;
  grid-template-rows: minmax(220px, auto) minmax(0, 1fr);
  gap: 16px;
  min-height: 0;
  align-content: stretch;
  overflow: hidden;
  padding-right: 2px;
}

.experience-sidebar.is-collapsed {
  grid-template-rows: auto auto;
}

.experience-sidebar-card,
.experience-progress-card,
.experience-chat-shell {
  border: 1px solid #e4e4e7;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 16px 30px rgba(15, 23, 42, 0.04);
  min-height: 0;
  overflow: hidden;
}

.experience-sidebar-card {
  padding: 14px 12px 12px;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.experience-sidebar-card.is-collapsed {
  height: auto;
  padding-bottom: 10px;
}

.experience-sidebar-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: 10px;
  margin-bottom: 14px;
}

.experience-sidebar-kicker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: #18181b;
  box-shadow: none;
  font-size: 11px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.04em;
  line-height: 1;
}

.experience-sidebar-title {
  font-size: 15px;
  font-weight: 650;
  color: #1f2937;
}

.experience-agent-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.4) transparent;
}

.experience-agent-list.is-collapsed {
  flex: 0 0 auto;
  overflow: hidden;
  padding-right: 0;
  gap: 4px;
}

.experience-agent-list::-webkit-scrollbar {
  width: 8px;
}

.experience-agent-list::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.38);
  background-clip: padding-box;
}

.experience-agent-item {
  width: calc(100% - 10px);
  max-width: calc(100% - 10px);
  margin-inline: auto;
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
  overflow: hidden;
  transition: background 140ms ease, border-color 140ms ease, box-shadow 140ms ease;
}

.experience-agent-item:hover,
.experience-agent-item.is-active {
  border-color: #e4e4e7;
  background: #f4f4f5;
  box-shadow: none;
}

.experience-agent-item.is-top-level {
  border-color: transparent;
  background: transparent;
}

.experience-agent-item.is-top-level:hover,
.experience-agent-item.is-top-level.is-active {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.experience-agent-item.is-peer-top-level::before {
  content: none;
}

.experience-agent-item.is-subagent {
  width: calc(100% - 28px);
  max-width: calc(100% - 28px);
  margin-left: 18px;
  padding: 7px 10px;
  border-color: rgba(228, 228, 231, 0.78);
  background: rgba(250, 250, 251, 0.84);
}

.experience-agent-item.is-subagent:hover,
.experience-agent-item.is-subagent.is-active {
  border-color: #e4e4e7;
  background: #f6f6f8;
}

.experience-agent-avatar,
.experience-chat-header-avatar,
.experience-chat-message-avatar {
  object-fit: cover;
  object-position: center;
  border-radius: 999px;
}

.experience-agent-avatar {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
}

.experience-agent-copy {
  min-width: 0;
  flex: 1 1 auto;
}

.experience-agent-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  width: 100%;
}

.experience-agent-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 600;
  color: #111827;
}

.experience-agent-badge {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 72px;
  padding: 2px 5px;
  border-radius: 999px;
  background: #f2f4f8;
  font-size: 9px;
  font-weight: 700;
  color: #7c8596;
  text-transform: lowercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.experience-agent-badge.is-main {
  max-width: none;
  padding: 3px 8px;
  background: #18181b;
  color: #ffffff;
  text-transform: none;
}

.experience-agent-chevron {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  margin-left: auto;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #71717a;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    background 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}

.experience-agent-chevron:hover {
  background: #e5e7eb;
  color: #111827;
}

.experience-agent-chevron svg {
  width: 14px;
  height: 14px;
  display: block;
}

.experience-agent-chevron.is-expanded svg {
  transform: rotate(180deg);
}

.experience-progress-card {
  padding: 18px 12px 12px;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.experience-progress-head {
  padding-inline: 10px;
  margin-bottom: 8px;
}

.experience-progress-title {
  font-size: 14px;
  font-weight: 650;
  color: #111827;
}

.experience-progress-summary {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding-inline: 10px;
  margin-bottom: 12px;
}

.experience-progress-rate {
  font-size: 13px;
  line-height: 1.2;
  color: #111827;
  text-align: right;
  white-space: nowrap;
  flex-shrink: 0;
  align-self: flex-end;
}

.experience-progress-rate strong {
  font-weight: 650;
}

.experience-progress-meter {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  min-height: 10px;
  width: 100%;
  min-width: 0;
  flex: none;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 2px;
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.35) transparent;
}

.experience-progress-meter.is-dense {
  gap: 4px;
}

.experience-progress-meter.is-dense .experience-progress-meter-dot {
  width: 6px;
  height: 6px;
}

.experience-progress-meter.is-dense .experience-progress-meter-dot.is-active {
  box-shadow: 0 0 0 2px rgba(139, 92, 246, 0.22);
}

.experience-progress-meter-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e4e4e7;
  flex-shrink: 0;
}

.experience-progress-meter-dot.is-completed {
  background: #8b5cf6;
}

.experience-progress-meter-dot.is-active {
  background: #8b5cf6;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.22);
}

.experience-progress-list {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 2px 4px 8px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.4) transparent;
}

.experience-progress-item {
  width: calc(100% - 10px);
  max-width: calc(100% - 10px);
  margin-inline: auto;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex: 0 0 auto;
  flex-shrink: 0;
  padding: 8px 10px;
  border-radius: 12px;
  background: transparent;
  border: none;
  font-size: 12px;
  color: #52525b;
  min-height: auto;
  box-sizing: border-box;
  overflow: visible;
}

.experience-progress-item.is-completed {
  color: #3f3f46;
}

.experience-progress-item.is-active {
  color: #4c1d95;
}

.experience-progress-dot {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  margin-top: 1px;
  border-radius: 999px;
  border: 1px solid #e3e7ee;
  background: radial-gradient(circle at center, #ffffff 0 30%, transparent 31%);
  box-shadow: inset 0 0 0 3px #f8fafc;
}

.experience-progress-item.is-completed .experience-progress-dot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-color: #86efac;
  background: #ecfdf5;
  box-shadow: none;
  color: #16a34a;
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
}

.experience-progress-item.is-completed .experience-progress-dot::before {
  content: '✓';
}

.experience-progress-item.is-active .experience-progress-dot {
  border: 2px solid rgba(139, 92, 246, 0.22);
  border-top-color: #8b5cf6;
  background: transparent;
  box-shadow: none;
  animation: experience-progress-dot-spin 0.9s linear infinite;
}

@keyframes experience-progress-dot-spin {
  to {
    transform: rotate(360deg);
  }
}

.experience-progress-copy {
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 2px;
}

.experience-progress-copy > span,
.experience-progress-copy > small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: normal;
}

.experience-progress-copy > span {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}

.experience-progress-copy small {
  font-size: 12px;
  line-height: 1.3;
  color: #71717a;
}

.experience-progress-item.is-active .experience-progress-running-label {
  color: #7c3aed;
  font-weight: 600;
}

.experience-progress-item.is-approval,
.experience-progress-item.is-branch {
  align-items: flex-start;
  padding-top: 10px;
  padding-bottom: 10px;
}

.experience-progress-item.is-approval .experience-progress-dot,
.experience-progress-item.is-branch .experience-progress-dot {
  margin-top: 2px;
}

.experience-progress-approval-meta {
  font-size: 12px;
  line-height: 1.35;
  color: #71717a;
}

.experience-progress-branch-meta {
  font-size: 12px;
  line-height: 1.35;
  color: #71717a;
}

.experience-progress-approval-result {
  margin-top: 8px;
  padding: 10px;
  border-radius: 10px;
  background: #f7f7f4;
  border: 1px solid #ecece8;
}

.experience-progress-approval-result-label {
  margin-bottom: 8px;
  font-size: 10px;
  line-height: 1.3;
  color: #71717a;
}

.experience-progress-approval-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.experience-progress-approval-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: #f4f4f5;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
  color: #a1a1aa;
}

.experience-progress-approval-pill.is-selected.is-approved {
  border-color: #86efac;
  background: #ecfdf5;
  color: #15803d;
}

.experience-progress-approval-pill.is-selected.is-rejected {
  border-color: #fca5a5;
  background: #fef2f2;
  color: #b91c1c;
}

.experience-progress-item.is-active .experience-progress-approval-result {
  background: #f3f1ff;
  border-color: #e4e4f0;
}

.experience-progress-item.is-active .experience-progress-approval-pill {
  background: #ebe9fe;
  color: #a1a1aa;
}

.experience-progress-branch-paths {
  margin-top: 8px;
  padding: 10px;
  border-radius: 10px;
  background: #f7f7f4;
  border: 1px solid #ecece8;
}

.experience-progress-branch-paths-label {
  margin-bottom: 8px;
  font-size: 10px;
  line-height: 1.3;
  color: #71717a;
}

.experience-progress-branch-path-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.experience-progress-branch-path-pill {
  display: inline-flex;
  align-items: center;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid #e4e4e7;
  background: #ffffff;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
  color: #3f3f46;
}

.experience-progress-branch-path-pill.is-selected {
  border-color: #86efac;
  background: #ecfdf5;
  color: #15803d;
}

.experience-progress-item.is-active .experience-progress-branch-paths {
  background: #f3f1ff;
  border-color: #e4e4f0;
}

.experience-progress-item.is-active .experience-progress-branch-path-pill:not(.is-selected) {
  background: #ffffff;
  border-color: #ddd6fe;
  color: #6b7280;
}

.experience-progress-item.is-branch-placeholder {
  align-items: flex-start;
  padding-top: 2px;
  padding-bottom: 6px;
}

