    transform: scale(1.02);
  }
  45% {
    left: 12px;
    top: 3px;
    z-index: 3;
    transform: scale(0.98);
  }
  46%,
  100% {
    z-index: 1;
  }
  100% {
    left: 4px;
    top: 6px;
    transform: scale(1);
  }
}

@keyframes joyce-handoff-avatar-to {
  0% {
    left: 4px;
    top: 6px;
