/* —— 演示：登录页（简约科技 3D 背景） —— */
.login-page {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  height: 100%;
  box-sizing: border-box;
  padding: 24px 16px;
  overflow: hidden;
  background: linear-gradient(180deg, #f5f6f8 0%, #fafbfc 48%, #f5f6f8 100%);
  color-scheme: light;
  color: #18181b;
  font-family: var(--font-sans);
}

.login-page-bg {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.login-page-bg-silk {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(245, 246, 248, 0.82) 0%, rgba(250, 251, 252, 0.78) 48%, rgba(245, 246, 248, 0.82) 100%);
  pointer-events: none;
}

.login-page-bg-silk-wave {
  position: absolute;
  top: -42%;
  left: -130%;
  width: 380%;
  height: 200%;
  pointer-events: none;
  will-change: transform;
}

.login-page-bg-silk-wave-a {
  background: repeating-linear-gradient(
    100deg,
    rgba(255, 255, 255, 0) 0px,
    rgba(255, 255, 255, 0) 130px,
    rgba(210, 212, 220, 0.18) 220px,
    rgba(244, 245, 249, 0.28) 300px,
    rgba(255, 255, 255, 0) 385px
  );
  filter: blur(6px);
  opacity: 0.42;
  animation: login-page-silk-drift-a 16s linear infinite;
}

.login-page-bg-silk-wave-b {
  background: repeating-linear-gradient(
    96deg,
    rgba(255, 255, 255, 0) 0px,
    rgba(255, 255, 255, 0) 175px,
    rgba(220, 222, 230, 0.14) 260px,
    rgba(255, 255, 255, 0) 345px
  );
  filter: blur(10px);
  opacity: 0.32;
  animation: login-page-silk-drift-b 20s linear infinite reverse;
}

@keyframes login-page-silk-drift-a {
  from {
    transform: translate3d(0, 0, 0);
  }

  to {
    transform: translate3d(-380px, 18px, 0);
  }
}

@keyframes login-page-silk-drift-b {
  from {
    transform: translate3d(0, 0, 0);
  }

  to {
    transform: translate3d(330px, -14px, 0);
  }
}

.login-page-bg-glow {
  position: absolute;
  top: 0;
  left: 50%;
  width: min(920px, 105%);
  height: 58%;
  z-index: 1;
  transform: translateX(-50%);
  background:
    radial-gradient(ellipse at 50% 35%, rgba(255, 255, 255, 0.55) 0%, transparent 58%),
    radial-gradient(ellipse at 18% 62%, rgba(218, 220, 228, 0.22) 0%, transparent 52%),
    radial-gradient(ellipse at 82% 48%, rgba(224, 226, 232, 0.18) 0%, transparent 50%);
  filter: blur(22px);
  animation: login-page-glow-pulse 8s ease-in-out infinite alternate;
  pointer-events: none;
}

.login-page-bg-dots {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: radial-gradient(circle, rgba(0, 0, 0, 0.09) 1px, transparent 1px);
  background-size: 26px 26px;
  background-position: 0 0;
  opacity: 0.82;
  -webkit-mask-image: radial-gradient(ellipse at 50% 40%, black 0%, transparent 88%);
  mask-image: radial-gradient(ellipse at 50% 40%, black 0%, transparent 88%);
  animation: login-page-dots-drift 20s linear infinite;
  pointer-events: none;
}

@keyframes login-page-glow-pulse {
  from {
    opacity: 0.55;
    filter: blur(20px);
  }

  to {
    opacity: 0.78;
    filter: blur(26px);
  }
}

@keyframes login-page-dots-drift {
  from {
    background-position: 0 0;
  }

  to {
    background-position: 24px 24px;
  }
}

.login-page-shell {
