.plan-agent-create-modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: #71717a;
  font-size: 22px;
  line-height: 1;
  font-weight: 400;
  cursor: pointer;
  box-sizing: border-box;
}

.plan-agent-create-modal-close:hover {
  background: #f4f4f5;
  color: #18181b;
}

.plan-agent-create-modal-close:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

.plan-agent-create-modal-icon {
  display: flex;
  justify-content: center;
  margin: 0 0 14px;
  line-height: 0;
}

.plan-agent-create-modal-title {
  margin: 0 0 12px;
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.02em;
  color: #0f172a;
}

.plan-agent-create-modal-status {
  margin: 0 0 18px;
  min-height: 1.5em;
  font-size: 14px;
  color: #64748b;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 2px;
}

.plan-agent-create-modal-status--done {
  color: #059669;
  font-weight: 600;
}

.plan-agent-create-modal-dots {
  display: inline-flex;
  gap: 3px;
  align-items: center;
  padding-left: 2px;
}

.plan-agent-create-modal-dots > span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #6366f1;
  animation: plan-agent-create-modal-dot 1.1s ease-in-out infinite both;
}

.plan-agent-create-modal-dots > span:nth-child(2) {
  animation-delay: 0.15s;
}

.plan-agent-create-modal-dots > span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes plan-agent-create-modal-dot {
  0%,
  80%,
  100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

.plan-agent-create-modal-bar {
  height: 8px;
  margin: 0 0 20px;
  border-radius: 999px;
  background: #e8e8ec;
  overflow: hidden;
  box-sizing: border-box;
}

.plan-agent-create-modal-bar-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #a78bfa 0%, #6366f1 45%, #2563eb 100%);
