}

.plan-agent-create-modal-steps {
  margin: 0;
  padding: 14px 16px 12px;
  list-style: none;
  text-align: left;
  border-radius: 12px;
  background: #f4f4f6;
  border: 1px solid #e8e8ed;
  box-sizing: border-box;
}

.plan-agent-create-modal-step {
