  gap: 12px;
  padding: 10px 0;
  font-size: 14px;
  line-height: 1.45;
  color: #71717a;
  border-top: 1px solid #e4e4e9;
}

.plan-agent-create-modal-step:first-child {
  border-top: none;
  padding-top: 2px;
}

.plan-agent-create-modal-step-num {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: #71717a;
  background: #e4e4e9;
}

.plan-agent-create-modal-step.is-active .plan-agent-create-modal-step-num {
  color: #ffffff;
  background: linear-gradient(135deg, #6366f1, #2563eb);
}

.plan-agent-create-modal-step.is-active .plan-agent-create-modal-step-label {
  color: #18181b;
  font-weight: 600;
}

.plan-agent-create-modal-step.is-complete .plan-agent-create-modal-step-num {
  color: #ffffff;
  background: #059669;
}

