    justify-items: stretch;
  }

  .skills-config-detail-filebar-actions,
  .skills-config-detail-filebar-actions.is-right {
    justify-content: flex-start;
  }

  .skills-config-detail-topbar {
    align-items: flex-start;
  }

  .skills-config-detail-title {
    font-size: 20px;
  }

  .skills-config-preview-card {
    padding: 22px 20px;
  }

  .skills-config-preview-content {
    font-size: 14px;
    line-height: 1.8;
  }

  .skills-config-editor-shell,
  .skills-config-editor-main {
    min-height: 420px;
  }

  .skills-config-editor-main .skills-config-editor {
    min-height: 392px;
  }
}

/* Workspace schedule node card */
.scenario-workflow-card--schedule.scenario-workflow-card--workspace-extra-schedule {
  display: flex;
  flex-direction: column;
  min-height: var(--workspace-extra-node-min-h, 88px);
  padding: 0;
  overflow: hidden;
}

.scenario-workflow-card-schedule-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 36px;
  padding: 8px 12px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  box-sizing: border-box;
}

.scenario-workflow-card-schedule-title {
  min-width: 0;
  flex: 1 1 auto;
  font-size: 13px;
  font-weight: 600;
  color: #1e293b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scenario-workflow-card-schedule-body {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 10px 12px;
  background: #ffffff;
  box-sizing: border-box;
}

.scenario-workflow-card-schedule-clock {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  color: #64748b;
}

.scenario-workflow-card-schedule-summary {
  min-width: 0;
  font-size: 12px;
  line-height: 1.4;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scenario-workflow-card--schedule-accent-on {
  outline: 2px solid rgba(37, 99, 235, 0.35);
  outline-offset: 0;
}

.scenario-workflow-card-pill--schedule {
  background: #eef2ff;
  color: #4338ca;
}

.scenario-workflow-card-icon-wrap--schedule {
  color: #4338ca;
  background: #eef2ff;
}

.scenario-workflow-card--workspace-extra-schedule.scenario-workflow-node--workspace-extra > .scenario-workflow-card {
  width: 100%;
}

/* Workspace schedule drawer */
.scenario-schedule-drawer-middle {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.scenario-schedule-drawer-section-title {
  margin: 0 0 10px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-heading);
}

.scenario-schedule-drawer-preset-panel,
.scenario-schedule-drawer-custom-panel {
  padding: 14px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #fafafa;
  box-sizing: border-box;
}

.scenario-schedule-drawer-frequency-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.scenario-schedule-drawer-frequency-btn {
  flex: 1 1 calc(50% - 4px);
  min-width: 120px;
  min-height: 34px;
  padding: 6px 10px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  background: #ffffff;
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  color: #52525b;
  cursor: pointer;
  box-sizing: border-box;
}

.scenario-schedule-drawer-frequency-btn:hover {
  border-color: #93c5fd;
  color: #2563eb;
}

.scenario-schedule-drawer-frequency-btn--active {
  border-color: #2563eb;
  color: #2563eb;
  background: #eff6ff;
}

.scenario-schedule-drawer-interval-field {
  margin-bottom: 14px;
}

.scenario-schedule-drawer-interval-label {
  display: block;
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 500;
  color: #71717a;
}

.scenario-schedule-drawer-weekday-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.scenario-schedule-drawer-weekday-btn {
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid #d4d4d8;
  border-radius: 999px;
  background: #ffffff;
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  color: #52525b;
  cursor: pointer;
}

.scenario-schedule-drawer-weekday-btn:hover {
  border-color: #93c5fd;
  color: #2563eb;
}

.scenario-schedule-drawer-weekday-btn--active {
  border-color: #2563eb;
  color: #2563eb;
  background: #eff6ff;
}

.scenario-schedule-drawer-time-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}

.scenario-schedule-drawer-time-label {
  font-size: 13px;
  font-weight: 500;
  color: #52525b;
}

.scenario-schedule-drawer-time-select {
  min-width: 72px;
}

.scenario-schedule-drawer-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid #e4e4e7;
  font-size: 12px;
  line-height: 1.45;
  color: #64748b;
}

.scenario-schedule-drawer-summary-icon {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  color: #94a3b8;
}
